package com.vit.archds.controller; import com.vit.archds.dto.AuthDtos.*; import com.vit.archds.entity.User; import com.vit.archds.security.CurrentUserProvider; import com.vit.archds.service.AuthService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController { private final AuthService auth; private final CurrentUserProvider current; public AuthController(AuthService a,CurrentUserProvider c){auth=a;current=c;} @PostMapping("/register") public AuthResponse register(@Valid @RequestBody Register r){return auth.register(r);} @PostMapping("/login") public AuthResponse login(@Valid @RequestBody Login r){return auth.login(r);} @GetMapping("/me") public Map<String,Object> me(){User u=current.require();return Map.of("id",u.getId(),"name",u.getName(),"email",u.getEmail(),"role",u.getRole().name());} }
